public static string CheckIntegerInRange(string input, int lowerBound, int upperBound)
{
    // Remove leading and trailing spaces
    input = input.Trim();

    // Check if the string is empty
    if (input.Length == 0)
    {
        return "Input is empty";
    }

    // Check if the string starts with a positive or negative sign
    int sign = 1;
    int index = 0;
    if (input[0] == '-')
    {
        sign = -1;
        index++;
    }
    else if (input[0] == '+')
    {
        index++;
    }

    // Check if the string contains only digits
    for (int i = index; i < input.Length; i++)
    {
        if (!Char.IsDigit(input[i]))
        {
            return "Input contains non-digit characters";
        }
    }

    // Parse the string as an integer
    int number;
    if (!Int32.TryParse(input, out number))
    {
        return "Input is not a valid integer";
    }

    // Check if the number is within the specified range
    if (number < lowerBound || number > upperBound)
    {
        return "Input is out of range";
    }

    // Return the valid number as a string
    return (number * sign).ToString();
}
