using System;
using System.Collections.Generic;
using System.Globalization;

public class Program
{
    public static bool ArePermutations(string input1, string input2)
    {
        // Remove whitespace and punctuation marks, and convert to lowercase
        string normalizedInput1 = NormalizeString(input1);
        string normalizedInput2 = NormalizeString(input2);

        // Check if the lengths of the normalized strings are equal
        if (normalizedInput1.Length != normalizedInput2.Length)
        {
            return false;
        }

        // Create character frequency dictionaries for both strings
        Dictionary<char, int> charFrequency1 = GetCharFrequency(normalizedInput1);
        Dictionary<char, int> charFrequency2 = GetCharFrequency(normalizedInput2);

        // Check if the character frequencies are equal
        foreach (var kvp in charFrequency1)
        {
            char key = kvp.Key;
            int value = kvp.Value;
            if (!charFrequency2.ContainsKey(key) || charFrequency2[key] != value)
            {
                return false;
            }
        }

        return true;
    }

    private static string NormalizeString(string input)
    {
        // Remove whitespace and punctuation marks
        string normalizedInput = new string(
            input
            .Normalize(NormalizationForm.FormD)
            .Where(c => CharUnicodeInfo.GetUnicodeCategory(c) != UnicodeCategory.NonSpacingMark && !char.IsPunctuation(c))
            .ToArray()
        );

        // Convert to lowercase
        normalizedInput = normalizedInput.ToLower();

        return normalizedInput;
    }

    private static Dictionary<char, int> GetCharFrequency(string input)
    {
        // Create character frequency dictionary
        Dictionary<char, int> charFrequency = new Dictionary<char, int>();

        foreach (char c in input)
        {
            if (charFrequency.ContainsKey(c))
            {
                charFrequency[c]++;
            }
            else
            {
                charFrequency[c] = 1;
            }
        }

        return charFrequency;
    }

    public static void Main(string[] args)
    {
        string input1 = "abc";
        string input2 = "a bc";
        Console.WriteLine(ArePermutations(input1, input2));  // true

        input1 = "abc";
        input2 = "ABC";
        Console.WriteLine(ArePermutations(input1, input2));  // false

        input1 = "ça va?";
        input2 = "va çaa?";
        Console.WriteLine(ArePermutations(input1, input2));  // true

        input1 = "I ❤️ programming!";
        input2 = "Programming is ❤️!";
        Console.WriteLine(ArePermutations(input1, input2));  // true

        input1 = "こんにちは";
        input2 = "んにちはこ";
        Console.WriteLine(ArePermutations(input1, input2));  // true
    }
}
```

This function uses the `NormalizeString` method to remove whitespace characters, punctuation marks, and convert the strings to lowercase. The `GetCharFrequency` method is used to create character frequency dictionaries for both strings. Finally, the function checks if the character frequencies are equal. The function has a time complexity of O(n log n) or better, as the `NormalizeString` method has a time complexity of O(n), and creating the character frequency dictionaries and checking the frequencies both have a time complexity of O(n).

