public static int CalculateMedian(int[] numbers)
{
    if (numbers.Length == 0)
    {
        return 0;
    }

    if (numbers.Length == 1)
    {
        return numbers[0];
    }

    int[] sortedNumbers = MergeSort(numbers);

    int middleIndex = sortedNumbers.Length / 2;

    if (sortedNumbers.Length % 2 == 0)
    {
        return (sortedNumbers[middleIndex] + sortedNumbers[middleIndex - 1]) / 2;
