Here is an example implementation of a method that finds the longest common subsequence of two strings in PascalABC.NET:

```csharp
using System;
using System.Text;

class Program
{
    static string FindLongestCommonSubsequence(string s1, string s2)
    {
        // Handle the case where either string is null or empty
        if (string.IsNullOrEmpty(s1) || string.IsNullOrEmpty(s2))
        {
            return string.Empty;
        }

        // Remove special characters and numbers from the strings
        StringBuilder sb1 = new StringBuilder();
        StringBuilder sb2 = new StringBuilder();

        foreach (char c in s1)
        {
            if (char.IsLetter(c))
            {
                sb1.Append(c);
            }
        }

        foreach (char c in s2)
        {
            if (char.IsLetter(c))
            {
                sb2.Append(c);
            }
        }

        string cleanedS1 = sb1.ToString();
        string cleanedS2 = sb2.ToString();

        // Initialize a 2D array to store the lengths of common subsequences
        int[,] dp = new int[cleanedS1.Length + 1, cleanedS2.Length + 1];

        // Compute the lengths of common subsequences
        for (int i = 1; i <= cleanedS1.Length; i++)
        {
            for (int j = 1; j <= cleanedS2.Length; j++)
            {
                if (cleanedS1[i - 1] == cleanedS2[j - 1])
                {
                    dp[i, j] = dp[i - 1, j - 1] + 1;
                }
                else
                {
                    dp[i, j] = Math.Max(dp[i - 1, j], dp[i, j - 1]);
                }
            }
        }

        // Build the longest common subsequence
        StringBuilder result = new StringBuilder();
        int x = cleanedS1.Length;
        int y = cleanedS2.Length;

        while (x > 0 && y > 0)
        {
            if (cleanedS1[x - 1] == cleanedS2[y - 1])
            {
                result.Insert(0, cleanedS1[x - 1]);
                x--;
                y--;
            }
            else if (dp[x - 1, y] > dp[x, y - 1])
            {
                x--;
            }
            else
            {
                y--;
            }
        }

        return result.ToString();
    }

    static void Main(string[] args)
    {
        string s1 = "ABC123DEF";
        string s2 = "AC#D$EF";

        string longestCommonSubsequence = FindLongestCommonSubsequence(s1, s2);
        Console.WriteLine(longestCommonSubsequence);
    }
}
```

In this example, we first handle the case where either string is null or empty by returning an empty string. Then, we remove any special characters and numbers from the strings using a `StringBuilder` and the `char.IsLetter` method. 

Next, we use dynamic programming to compute the lengths of common subsequences of the cleaned strings. We initialize a 2D array `dp` where `dp[i, j]` represents the length of the longest common subsequence of the first `i` characters of `cleanedS1` and the first `j` characters of `cleanedS2`.

We iterate through the characters of `cleanedS1` and `cleanedS2` and update `dp` accordingly. If the characters are equal, we add 1 to the length of the longest common subsequence obtained by removing both characters from the strings. Otherwise, we take the maximum length obtained by either removing the last character from `cleanedS1` or removing the last character from `cleanedS2`.

After computing the lengths of common subsequences, we build the longest common subsequence by backtracking through `dp`. Starting from the last characters of `cleanedS1` and `cleanedS2`, we compare the characters and move diagonally in `dp` if they are equal. If they are not equal, we move either left or up in `dp`, depending on which direction leads to a longer subsequence.

Finally, we return the longest common subsequence as a string. In this example, the output will be "ACDEF".

