```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class EventListener<TEventArgs>
{
    private readonly object lockObject = new object();
    private readonly Dictionary<Guid, EventHandler<TEventArgs>> eventHandlers = new Dictionary<Guid, EventHandler<TEventArgs>>();
    private readonly Dictionary<Guid, int> eventPriorities = new Dictionary<Guid, int>();
    private readonly Dictionary<Guid, bool> canceledEvents = new Dictionary<Guid, bool>();
    private int totalEventsFired = 0;

    public Guid Subscribe(EventHandler<TEventArgs> eventHandler, int priority = 0)
    {
        var eventId = Guid.NewGuid();

        lock (lockObject)
        {
            eventHandlers[eventId] = eventHandler;
            eventPriorities[eventId] = priority;
        }

        return eventId;
    }

    public void Unsubscribe(Guid eventId)
    {
        lock (lockObject)
        {
            eventHandlers.Remove(eventId);
            eventPriorities.Remove(eventId);
        }
    }

    public IEnumerable<Guid> GetSubscribedEvents()
    {
        lock (lockObject)
        {
            return eventHandlers.Keys.ToList();
        }
    }

    public void ClearSubscribedEvents()
    {
        lock (lockObject)
        {
            eventHandlers.Clear();
            eventPriorities.Clear();
        }
    }

    public bool IsEventSubscribed(Guid eventId)
    {
        lock (lockObject)
        {
            return eventHandlers.ContainsKey(eventId);
        }
    }

    public int GetNumSubscribedEvents()
    {
        lock (lockObject)
        {
            return eventHandlers.Count;
        }
    }

    public int GetNumEventsFired()
    {
        lock (lockObject)
        {
            return totalEventsFired;
        }
    }

    public void SetEventPriority(Guid eventId, int priority)
    {
        lock (lockObject)
        {
            eventPriorities[eventId] = priority;
        }
    }

    public int GetEventPriority(Guid eventId)
    {
        lock (lockObject)
        {
            return eventPriorities[eventId];
        }
    }

    public IEnumerable<Guid> GetEventsSortedByPriority()
    {
        lock (lockObject)
        {
            return eventHandlers.Keys.OrderBy(eventId => eventPriorities[eventId]).ToList();
        }
    }

    public void FireEvent(object sender, TEventArgs eventArgs)
    {
        var eventId = Guid.NewGuid();

        lock (lockObject)
        {
            totalEventsFired++;
            canceledEvents[eventId] = false;
        }

        foreach (var handler in GetEventsSortedByPriority())
        {
            lock (lockObject)
            {
                if (canceledEvents[eventId])
                {
                    canceledEvents.Remove(eventId);
                    return;
                }
            }

            eventHandlers[handler]?.Invoke(sender, eventArgs);
        }
    }

    public void CancelEvent(Guid eventId)
    {
        lock (lockObject)
        {
            canceledEvents[eventId] = true;
        }
    }

    public IEnumerable<Guid> GetCanceledEvents()
    {
        lock (lockObject)
        {
            return canceledEvents.Keys.ToList();
        }
    }

    public void ClearCanceledEvents()
    {
        lock (lockObject)
        {
            canceledEvents.Clear();
        }
    }

    public bool IsEventCanceled(Guid eventId)
    {
        lock (lockObject)
        {
            return canceledEvents.ContainsKey(eventId);
        }
    }

    public int GetNumCanceledEvents()
    {
        lock (lockObject)
        {
            return canceledEvents.Count;
        }
    }
}
```

This implementation provides a thread-safe event listener class that supports multiple events, event priorities, event cancellation, and various methods to manage and retrieve information about the events.

