    public static decimal MultiplyDecimalByDigitSum(decimal number)
    {
        // Check if the number is negative
        if (number < 0)
        {
            throw new ArgumentException("Number cannot be negative");
        }

        // Convert the decimal number to string
        string numberStr = number.ToString();

        // Check if the number of digits exceeds the maximum limit
        if (numberStr.Length > 10)
        {
            throw new ArgumentException("Number cannot exceed 10 digits");
        }

        // Calculate the sum of the digits
        int digitSum = 0;
        foreach (char digitChar in numberStr)
        {
            if (char.IsDigit(digitChar))
            {
                digitSum += int.Parse(digitChar.ToString());
            }
        }

        // Calculate the factorial of the number of digits
        int numOfDigits = numberStr.Length;
        int factorial = 1;
        for (int i = 2; i <= numOfDigits; i++)
        {
            factorial *= i;
        }

        // Calculate the result
        decimal result = number * digitSum * factorial;

        return result;
    }

