    static int DoubleValue(int num)
    {
        if (num == 0)
            return 0;

        int sign = 1;

        // Check if the number is negative
        if (num < 0)
        {
            num = -num;
            sign = -1;
        }

        int doubleValue = num << 1; // Left shift the number by 1 to double its value

        // Check if the original number was negative
