        string normalizedStr = str.ToLower();

        int vowelCount = 0;
        bool ignoreNextConsonant = false;
        bool ignoreNextVowel = false;

        for (int i = 0; i < normalizedStr.Length; i++)
        {
            char currentChar = normalizedStr[i];

            if (ignoreNextVowel)
            {
                if (currentChar == ')' || currentChar == ']')
                {
                    ignoreNextVowel = false;
                }
                continue;
            }

            if (currentChar == '(' || currentChar == '[')
            {
                ignoreNextVowel = true;
                continue;
            }

            if (vowels.Contains(currentChar.ToString()))
            {
                if (!ignoreNextConsonant)
                {
                    vowelCount++;
                }
            }

            if (!ignoreNextConsonant && !vowels.Contains(currentChar.ToString()))
            {
                ignoreNextConsonant = true;
            }
            else if (currentChar == ' ' || currentChar == '.' || currentChar == ',' || currentChar == '!' || currentChar == '?')
            {
                ignoreNextConsonant = false;
            }
        }

        return vowelCount;
    }
