public static void ReverseString(ref string str)
{
    // Convert the string to a character array
    char[] characters = str.ToCharArray();

    // Get the length of the string
    int length = characters.Length;

    // Iterate over the first half of the array
    for (int i = 0; i < length / 2; i++)
    {
        // Swap the characters at the current index and its corresponding index from the end
        char temp = characters[i];
        characters[i] = characters[length - i - 1];
        characters[length - i - 1] = temp;
    }

    // Convert the character array back to a string
    str = new string(characters);
}
