```csharp
using System;
using System.Diagnostics;

public class Program
{
    private static Random random = new Random();
    private static Stopwatch stopwatch = new Stopwatch();

    public static void Main(string[] args)
    {
        stopwatch.Start();
        int generatedPrime = GenerateRandomPrimeNumber(1000, 2000);
        stopwatch.Stop();

        Console.WriteLine("Generated Prime Number: " + generatedPrime);
        Console.WriteLine("Time Taken: " + stopwatch.ElapsedMilliseconds + " ms");
    }

    private static int GenerateRandomPrimeNumber(int min, int max)
    {
        while (stopwatch.ElapsedMilliseconds < 1000)
        {
            int number = random.Next(min, max + 1);
            if (IsPrime(number))
                return number;
        }

        throw new TimeoutException("Time limit exceeded.");
    }

    private static bool IsPrime(int number)
    {
        if (number <= 1)
            return false;

        if (number <= 3)
            return true;

        if (number % 2 == 0 || number % 3 == 0)
            return false;

        for (int i = 5; i * i <= number; i += 6)
        {
            if (number % i == 0 || number % (i + 2) == 0)
                return false;
        }

        return true;
    }
}
```

Explanation:
1. The `GenerateRandomPrimeNumber` function takes a minimum and maximum range and generates a random number within that range using `random.Next(min, max + 1)`.
2. It then checks if the generated number is prime using the `IsPrime` function.
3. The `IsPrime` function checks if the number is less than or equal to 1 and returns false. If the number is 2 or 3, it returns true.
4. It then checks if the number is divisible by 2 or 3, returning false if it is.
5. The function uses a for loop starting from 5 and increments by 6 in each iteration. It checks if the number is divisible by `i` or `i + 2`, returning false if it is.
6. If none of the above conditions are met, it returns true, indicating that the number is prime.
7. The `stopwatch` is used to ensure that the code runs within the given time limit of 1 second. If the time limit is exceeded, a `TimeoutException` is thrown.

