using System;

class NumberToWordsConverter
{
    private static string[] units = { "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen" };
    private static string[] tens = { "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety" };

    public static string ConvertToWords(long number)
    {
        if (number == 0)
            return "zero";

        if (number < 0)
            return "minus " + ConvertToWords(Math.Abs(number));

        string words = "";

        if ((number / 1000000000000) > 0)
        {
            words += ConvertToWords(number / 1000000000000) + " trillion ";
            number %= 1000000000000;
        }

        if ((number / 1000000000) > 0)
        {
            words += ConvertToWords(number / 1000000000) + " billion ";
            number %= 1000000000;
        }

        if ((number / 1000000) > 0)
        {
            words += ConvertToWords(number / 1000000) + " million ";
            number %= 1000000;
        }

        if ((number / 1000) > 0)
        {
            words += ConvertToWords(number / 1000) + " thousand ";
            number %= 1000;
        }

        if ((number / 100) > 0)
        {
            words += ConvertToWords(number / 100) + " hundred ";
            number %= 100;
        }

        if (number > 0)
        {
            if (words != "")
                words += "and ";

            if (number < 20)
                words += units[number];
            else
            {
                words += tens[number / 10];
                if ((number % 10) > 0)
                    words += "-" + units[number % 10];
            }
        }

        return words.Trim();
    }

    static void Main(string[] args)
    {
        Console.Write("Enter a number: ");
        long number = Convert.ToInt64(Console.ReadLine());

        string words = ConvertToWords(number);
        Console.WriteLine("Number in words: " + words);

        Console.ReadLine();
    }
}
```

