using System;

namespace SumOfSeries
{
    class Program
    {
        static double CalculateSeriesSum(int n)
        {
            double sum = 1.0;

            for (int i = 2; i <= n; i++)
            {
                double term = 1.0;
                for (int j = 1; j <= i; j++)
                {
                    term *= (double)i / j;
                }
                sum += term;
            }

            return sum;
        }

        static void Main(string[] args)
        {
            int n = (int)Math.Pow(10, 6); // Example value: 10^6
            double sum = CalculateSeriesSum(n);
            Console.WriteLine("Sum of the series up to n = " + n + " is: " + sum);
        }
    }
}
```

