        char[] charArray = str.ToCharArray();
        Array.Reverse(charArray);

        string reversedString = "";
        char previousChar = '\0';

        foreach (char c in charArray)
        {
            if (c != previousChar)
            {
                reversedString += c;
                previousChar = c;
            }
        }

        return reversedString;
    }

    static int CountVowels(string str)
