public static int ReverseInteger(int number)
{
    int reversedNumber = 0;
    int sign = number < 0 ? -1 : 1;
    number *= sign;

    while (number > 0)
    {
        reversedNumber = (reversedNumber * 10) + (number % 10);
        number /= 10;
    }

    return reversedNumber * sign;
}
```

