public static bool IsUniqueCharacters(string str)
{
    int bitmap = 0;

    for (int i = 0; i < str.Length; i++)
    {
        int bitPosition = char.ToLower(str[i]) - 'a';

        if ((bitmap & (1 << bitPosition)) != 0)
        {
            return false;
        }

        bitmap |= (1 << bitPosition);
    }

    return true;
}
