using System;

class TriangleAreaCalculator
{
    static void Main()
    {
        // Prompt the user to enter the base value
        Console.Write("Enter the base of the triangle: ");
        string baseInput = Console.ReadLine();

        // Prompt the user to enter the height value
        Console.Write("Enter the height of the triangle: ");
        string heightInput = Console.ReadLine();

        int baseValue, heightValue;

        // Validate that the base value is a positive integer
        if (!int.TryParse(baseInput, out baseValue) || baseValue <= 0)
        {
            Console.WriteLine("Invalid base value! Please enter a positive integer.");
            return;
        }

        // Validate that the height value is a positive integer
        if (!int.TryParse(heightInput, out heightValue) || heightValue <= 0)
        {
            Console.WriteLine("Invalid height value! Please enter a positive integer.");
            return;
        }

        // Prompt the user to choose the calculation method
        Console.WriteLine("Choose the calculation method:");
        Console.WriteLine("1. Calculate using the formula (1/2 * base * height)");
        Console.WriteLine("2. Calculate using Heron's formula (enter the lengths of all three sides)");
        Console.Write("Enter your choice: ");
        string calculationMethodInput = Console.ReadLine();

        int calculationMethod;

        // Validate the calculation method choice
        if (!int.TryParse(calculationMethodInput, out calculationMethod) || (calculationMethod != 1 && calculationMethod != 2))
        {
            Console.WriteLine("Invalid calculation method choice! Please enter 1 or 2.");
            return;
        }

        double area = 0;

        // Calculate the area using the formula
        if (calculationMethod == 1)
        {
            area = 0.5 * baseValue * heightValue;
        }
        // Calculate the area using Heron's formula
        else if (calculationMethod == 2)
        {
            // Prompt the user to enter the lengths of all three sides
            Console.Write("Enter the length of side 1: ");
            string side1Input = Console.ReadLine();
            Console.Write("Enter the length of side 2: ");
            string side2Input = Console.ReadLine();
            Console.Write("Enter the length of side 3: ");
            string side3Input = Console.ReadLine();

            int side1, side2, side3;

            // Validate that the side lengths are positive integers
            if (!int.TryParse(side1Input, out side1) || side1 <= 0 ||
                !int.TryParse(side2Input, out side2) || side2 <= 0 ||
                !int.TryParse(side3Input, out side3) || side3 <= 0)
            {
                Console.WriteLine("Invalid side lengths! Please enter positive integers for all three sides.");
                return;
            }

            // Check if the side lengths can form a valid triangle
            if (side1 + side2 > side3 && side2 + side3 > side1 && side3 + side1 > side2)
            {
                // Calculate the area using Heron's formula
                double semiPerimeter = (side1 + side2 + side3) / 2.0;
                area = Math.Sqrt(semiPerimeter * (semiPerimeter - side1) * (semiPerimeter - side2) * (semiPerimeter - side3));
            }
            else
            {
                Console.WriteLine("Invalid side lengths! They cannot form a valid triangle.");
                return;
            }
        }

        // Round the calculated area to the nearest integer
        int roundedArea = (int)Math.Round(area);

        // Display the calculated area to the user
        Console.WriteLine("The area of the triangle is: " + roundedArea);
    }
}
