public static int StringToInteger(string str)
{
    // Trim leading and trailing white spaces
    str = str.Trim();

    // Check for empty string
    if (string.IsNullOrEmpty(str))
        return 0;

    // Check for optional leading sign
    bool isNegative = false;
    int startIndex = 0;
    if (str[0] == '+' || str[0] == '-')
    {
        if (str[0] == '-')
            isNegative = true;
        startIndex = 1;
    }

    // Check for hexadecimal input
    if (str.Length > startIndex + 2 && str[startIndex] == '0' && (str[startIndex + 1] == 'x' || str[startIndex + 1] == 'X'))
    {
        // Convert hexadecimal input
        int value = 0;
        for (int i = startIndex + 2; i < str.Length; i++)
        {
            char c = str[i];
            if (c >= '0' && c <= '9')
            {
                value = value * 16 + (c - '0');
            }
            else if (c >= 'a' && c <= 'f')
            {
                value = value * 16 + (c - 'a' + 10);
            }
            else if (c >= 'A' && c <= 'F')
            {
                value = value * 16 + (c - 'A' + 10);
            }
            else
            {
                // Return 0 if non-digit character encountered
                return 0;
            }
        }

        // Apply sign and check for range
        if (isNegative)
            value = -value;
        return value;
    }
    else
    {
        // Convert decimal input
        int value = 0;
        for (int i = startIndex; i < str.Length; i++)
        {
            char c = str[i];
            if (c >= '0' && c <= '9')
            {
                value = value * 10 + (c - '0');
            }
            else
            {
                // Return 0 if non-digit character encountered
                return 0;
            }
        }

        // Apply sign and check for range
        if (isNegative)
            value = -value;
        return value;
    }
}
