using System;

public class TwoDimensionalArraySearch
{
    public static (int, int) SearchValue(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int left = 0;
        int right = rows * cols - 1;

        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            int row = mid / cols;
            int col = mid % cols;
            int value = arr[row, col];

            if (value == target)
            {
                return (row, col);
            }
            else if (value < target)
            {
                left = mid + 1;
            }
            else
            {
                right = mid - 1;
            }
        }

        return (-1, -1);
    }

    public static int SearchRow(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int left = 0;
        int right = rows - 1;

        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            int value = arr[mid, 0];

            if (value == target)
            {
                return mid;
            }
            else if (value < target)
            {
                left = mid + 1;
            }
            else
            {
                right = mid - 1;
            }
        }

        return -1;
    }

    public static int SearchColumn(int[,] arr, int target)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);

        int left = 0;
        int right = cols - 1;

        while (left <= right)
        {
            int mid = left + (right - left) / 2;
            int value = arr[0, mid];

            if (value == target)
            {
                return mid;
            }
            else if (value < target)
            {
                left = mid + 1;
            }
            else
            {
                right = mid - 1;
            }
        }

        return -1;
    }

    public static (int, int) SearchSubmatrix(int[,] arr, int[,] submatrix)
    {
        int rows = arr.GetLength(0);
        int cols = arr.GetLength(1);
        int subRows = submatrix.GetLength(0);
        int subCols = submatrix.GetLength(1);

        for (int i = 0; i <= rows - subRows; i++)
        {
            for (int j = 0; j <= cols - subCols; j++)
            {
                bool found = true;

                for (int k = 0; k < subRows; k++)
                {
                    for (int l = 0; l < subCols; l++)
                    {
                        if (arr[i + k, j + l] != submatrix[k, l])
                        {
                            found = false;
                            break;
                        }
                    }

                    if (!found)
                    {
                        break;
                    }
                }

                if (found)
                {
                    return (i, j);
                }
            }
        }

        return (-1, -1);
    }
}
```

This implementation uses binary search algorithms to efficiently search for the target values. The `SearchValue` method performs a binary search on the entire two-dimensional array, while the `SearchRow` and `SearchColumn` methods perform binary searches on the rows and columns, respectively.

The `SearchSubmatrix` method performs a brute-force search for the submatrix, checking each possible position in the array. This is because binary search cannot be directly applied to a submatrix as it may not have the same sorted properties as the entire array.

Note that the code assumes the array is non-empty and the submatrix dimensions are valid. Additional error checking can be added if necessary.

