public static int FindThirdCommonElement(int[] array1, int[] array2)
{
    // Create two counters for tracking the frequency of elements
    int counter1 = 0;
    int counter2 = 0;

    // Initialize variables to store the first, second, and third common elements
    int firstCommon = int.MaxValue;
    int secondCommon = int.MaxValue;
    int thirdCommon = int.MaxValue;

    // Loop through the first array and update the counters accordingly
    for (int i = 0; i < array1.Length; i++)
    {
        if (counter1 == 0)
        {
            firstCommon = array1[i];
            counter1++;
        }
        else if (array1[i] == firstCommon)
        {
            counter1++;
        }
        else if (counter2 == 0)
        {
            secondCommon = array1[i];
            counter2++;
        }
        else if (array1[i] == secondCommon)
        {
            counter2++;
        }
        else
        {
            counter1--;
            counter2--;
        }
    }

    // Reset the counters for the second array
    counter1 = 0;
    counter2 = 0;

    // Loop through the second array and update the counters accordingly
    for (int i = 0; i < array2.Length; i++)
    {
        if (array2[i] == firstCommon)
        {
            counter1++;
        }
        else if (array2[i] == secondCommon)
        {
            counter2++;
        }
        else if (counter1 == 0)
        {
            firstCommon = array2[i];
            counter1++;
        }
        else if (counter2 == 0)
        {
            secondCommon = array2[i];
            counter2++;
        }
        else
        {
            counter1--;
            counter2--;
        }
    }

    // Check if the first common element is the third common element
    if (counter1 > 0)
    {
        thirdCommon = firstCommon;
    }

    // Check if the second common element is the third common element
    if (counter2 > 0)
    {
        thirdCommon = secondCommon;
    }

    // Return the third common element
    return thirdCommon;
}
