```csharp
using System;

class Fibonacci
{
    static void Main(string[] args)
    {
        Console.Write("Enter the value of n: ");
        int n = Convert.ToInt32(Console.ReadLine());

        BigInteger result = FindFibonacci(n);

        Console.WriteLine($"The {n}th Fibonacci number is: {result}");
    }

    static BigInteger FindFibonacci(int n)
    {
        BigInteger a = 0, b = 1, c = 0;

        if (n == 0)
            return a;

        for (int i = 2; i <= n; i++)
