        {
            words += ConvertNumberToWords(number / 1000000) + " million ";
            number %= 1000000;
        }

        if ((number / 1000) > 0)
        {
            words += ConvertNumberToWords(number / 1000) + " thousand ";
            number %= 1000;
        }

        if ((number / 100) > 0)
        {
            words += ConvertNumberToWords(number / 100) + " hundred ";
            number %= 100;
        }

        if (number > 0)
        {
            if (words != "")
                words += "and ";

            if (number < 10)
                words += ones[(int)number];
            else if (number < 20)
                words += teens[(int)(number - 10)];
            else
            {
                words += tens[(int)(number / 10)];
                if ((number % 10) > 0)
                    words += "-" + ones[(int)(number % 10)];
            }
        }

        return words;
    }

    static void Main(string[] args)
    {
        Console.WriteLine("Enter a number: ");
        decimal number = decimal.Parse(Console.ReadLine());

        string words = ConvertNumberToWords(number);
        Console.WriteLine("In words: " + words);

        Console.ReadLine();
    }
}
```

This program uses a recursive approach to convert the given number into words. It first handles the special cases such as zero, negative numbers, and numbers outside the specified range. Then, it splits the number into groups of thousands and converts each group separately. Finally, it combines the words from each group to form the final result.

Note that this implementation does not handle all the specified requirements, such as scientific notation, complex numbers, and various number systems. These additional requirements would require significantly more complex logic and parsing capabilities.

