Here's an example of a PascalABC.NET class that uses recursion to serialize a JSON object, including only properties with a specific attribute applied to them, with a specific data type, and excluding properties with a specific value:

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json;

public class CustomJsonSerializer
{
    private Type attributeType;
    private Type dataType;
    private object excludedValue;

    public CustomJsonSerializer(Type attributeType, Type dataType, object excludedValue)
    {
        this.attributeType = attributeType;
        this.dataType = dataType;
        this.excludedValue = excludedValue;
    }

    public string Serialize(object obj)
    {
        var properties = GetPropertiesWithAttribute(obj.GetType());

        var dict = new Dictionary<string, object>();
        foreach (var property in properties)
        {
            var value = property.GetValue(obj);
            if (value == null || value.Equals(excludedValue))
                continue;

            if (dataType.IsAssignableFrom(property.PropertyType))
            {
                var propertyName = property.GetCustomAttribute<JsonPropertyAttribute>()?.PropertyName ?? property.Name;
                if (value is string)
                    dict[propertyName] = value;
                else
                    dict[propertyName] = Serialize(value);
            }
        }

        return JsonConvert.SerializeObject(dict);
    }

    private IEnumerable<PropertyInfo> GetPropertiesWithAttribute(Type type)
    {
        return type.GetProperties().Where(p => p.GetCustomAttribute(attributeType) != null);
    }
}
```

Here's an example usage of the `CustomJsonSerializer` class:

```csharp
