{
    static void Main()
    {
        try
        {
            Console.WriteLine("Enter a string: ");
            string input = Console.ReadLine();

            if (string.IsNullOrEmpty(input))
            {
                Console.WriteLine("Error: Input string is empty.");
                return;
            }

            Console.WriteLine("Original string: " + input);
            Console.WriteLine("Modified strings:");

            string reversedString = ReverseString(input);
            Console.WriteLine("Reversed string: " + reversedString);

            string upperCaseString = input.ToUpper();
            Console.WriteLine("Uppercase string: " + upperCaseString);

            string replacedVowelsString = ReplaceVowelsWithAsterisks(input);
