Here is the program in PascalABC.NET that sorts an array of integers in ascending order using the Bubble Sort algorithm and tracks the number of comparisons and swaps made during the sorting process:

```csharp
using System;

class BubbleSort
{
    static int comparisons = 0;
    static int swaps = 0;

    static void BubbleSortRecursive(int[] arr, int n)
    {
        if (n == 1)
            return;

        for (int i = 0; i < n - 1; i++)
        {
            if (arr[i] > arr[i + 1])
            {
                Swap(arr, i, i + 1);
            }
            comparisons++;
        }

        BubbleSortRecursive(arr, n - 1);
    }

    static void Swap(int[] arr, int i, int j)
    {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        swaps++;
    }

    static void Main()
    {
        int[] arr = { 64, 34, 25, 12, 22, 11, 90 };

        Console.WriteLine("Original Array: ");
        PrintArray(arr);

        BubbleSortRecursive(arr, arr.Length);

        Console.WriteLine("\nSorted Array: ");
        PrintArray(arr);

        Console.WriteLine("\nNumber of comparisons: " + comparisons);
        Console.WriteLine("Number of swaps: " + swaps);
    }

    static void PrintArray(int[] arr)
    {
        foreach (int num in arr)
