class Program
{
    static void Main(string[] args)
    {
        int[] arr = { 1, 2, 3, 4 };
        int n = 3;

        List<List<int>> combinations = GenerateCombinations(arr, n);

        foreach (List<int> combination in combinations)
        {
            Console.WriteLine(string.Join(", ", combination));
        }
    }

    static List<List<int>> GenerateCombinations(int[] arr, int n)
    {
        List<List<int>> combinations = new List<List<int>>();
        List<int> current = new List<int>();
        Array.Sort(arr);
        GenerateCombinationsHelper(arr, combinations, current, n, 0);
        return combinations;
    }

    static void GenerateCombinationsHelper(int[] arr, List<List<int>> combinations, List<int> current, int n, int start)
    {
        if (n == 0)
        {
            combinations.Add(new List<int>(current));
            return;
        }

        for (int i = start; i < arr.Length; i++)
        {
            if (i > start && arr[i] == arr[i - 1])
            {
                continue; // Skip duplicate elements
            }

            current.Add(arr[i]);
            GenerateCombinationsHelper(arr, combinations, current, n - 1, i + 1);
            current.RemoveAt(current.Count - 1);
        }
    }
}
```

This function uses a helper function `GenerateCombinationsHelper` to generate combinations recursively. It keeps track of the current combination in the `current` list and adds it to the `combinations` list when the desired length is reached.

To handle duplicate elements, we sort the array before generating combinations and skip duplicate elements in the loop. This ensures that each combination does not contain any repeated elements.

