```csharp
using System;

class Program
{
    static int FibonacciSearch(int[] arr, int element)
    {
        int n = arr.Length;
        int fib2 = 0;
        int fib1 = 1;
        int fib = fib2 + fib1;

        while (fib < n)
        {
            fib2 = fib1;
            fib1 = fib;
            fib = fib2 + fib1;
        }

        int offset = -1;

        while (fib > 1)
        {
            int i = Math.Min(offset + fib2, n - 1);

            if (arr[i] < element)
            {
                fib = fib1;
                fib1 = fib2;
                fib2 = fib - fib1;
                offset = i;
            }
            else if (arr[i] > element)
            {
                fib = fib2;
                fib1 = fib1 - fib2;
                fib2 = fib - fib1;
            }
            else
            {
                return i;
            }
        }

        if (fib1 == 1 && arr[offset + 1] == element)
        {
            return offset + 1;
        }

        return -1;
    }

    static void Main(string[] args)
    {
        int[] arr = { 2, 3, 4, 10, 14, 20, 26, 30, 40 };
        int element = 10;

        int index = FibonacciSearch(arr, element);

        if (index != -1)
        {
            Console.WriteLine("Element found at index " + index);
        }
        else
        {
            Console.WriteLine("Element not found");
        }
    }
}
```

This implementation first calculates the largest Fibonacci number that is less than or equal to the length of the array. It then uses this Fibonacci number to divide the array into two parts. It compares the element with the element at the midpoint of the current part. If the element is found, it returns the index. If the element is smaller, it updates the Fibonacci numbers and searches the left part of the array. If the element is larger, it updates the Fibonacci numbers and searches the right part of the array. This process continues until the element is found or the Fibonacci number becomes 1. If the Fibonacci number is 1 and the element at the next position is the target element, it returns the index of that position. Otherwise, it returns -1 to indicate that the element was not found.

To modify the algorithm to handle cases where the array may contain duplicate elements, you can update the condition for returning the index. Instead of immediately returning the index when the element is found, you can check if the previous element is also equal to the target element. If it is, you continue searching towards the left until you find the first occurrence of the element. Here's the modified code snippet:

