using System.Linq;

public class ServiceHandler
{
    public List<string> FilterRecords(List<string> records)
    {
        List<string> filteredRecords = new List<string>();

        foreach (string record in records)
        {
            if (IsPrime(record.Length) && ContainsTwoVowelsInReverseOrder(record) && IsAlphabeticalOrder(record))
            {
                filteredRecords.Add(record);
            }
        }

        return filteredRecords;
    }

    private bool IsPrime(int number)
    {
        if (number < 2) return false;

        for (int i = 2; i <= Math.Sqrt(number); i++)
        {
            if (number % i == 0) return false;
        }

        return true;
    }

    private bool ContainsTwoVowelsInReverseOrder(string word)
    {
        int vowelCount = 0;
        bool foundFirstVowel = false;

        for (int i = word.Length - 1; i >= 0; i--)
        {
            char c = char.ToLower(word[i]);
            if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u')
            {
                vowelCount++;
                if (!foundFirstVowel)
                {
                    foundFirstVowel = true;
                }
                else
                {
                    return true; // Found at least two vowels in reverse order
                }
            }
        }

        return false; // Less than two vowels in reverse order
    }

    private bool IsAlphabeticalOrder(string word)
    {
        for (int i = 1; i < word.Length; i++)
        {
            if (char.ToLower(word[i]) < char.ToLower(word[i - 1]))
            {
                return false; // Characters are not in alphabetical order
            }
        }

        return true; // Characters are in alphabetical order
    }
}
