```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter the number of strings:");
        int n = Convert.ToInt32(Console.ReadLine());

        Console.WriteLine("Enter the strings:");
        string[] strings = new string[n];
        for (int i = 0; i < n; i++)
        {
            strings[i] = Console.ReadLine();
        }

        SortStrings(strings);

        Console.WriteLine("Sorted strings:");
        foreach (string str in strings)
        {
            Console.WriteLine(str);
        }
    }

    static void SortStrings(string[] strings)
    {
        MergeSort(strings, 0, strings.Length - 1);
    }

    static void MergeSort(string[] strings, int left, int right)
    {
        if (left < right)
        {
            int mid = (left + right) / 2;

            MergeSort(strings, left, mid);
            MergeSort(strings, mid + 1, right);

            Merge(strings, left, mid, right);
        }
    }

    static void Merge(string[] strings, int left, int mid, int right)
    {
        int n1 = mid - left + 1;
        int n2 = right - mid;

        string[] leftArray = new string[n1];
        string[] rightArray = new string[n2];

        Array.Copy(strings, left, leftArray, 0, n1);
        Array.Copy(strings, mid + 1, rightArray, 0, n2);

        int i = 0, j = 0, k = left;

        while (i < n1 && j < n2)
        {
            if (CompareStrings(leftArray[i], rightArray[j]) <= 0)
            {
                strings[k++] = leftArray[i++];
            }
            else
            {
                strings[k++] = rightArray[j++];
            }
        }

        while (i < n1)
        {
            strings[k++] = leftArray[i++];
        }

        while (j < n2)
        {
            strings[k++] = rightArray[j++];
        }
    }

    static int CompareStrings(string a, string b)
    {
        int minLength = Math.Min(a.Length, b.Length);

        for (int i = 0; i < minLength; i++)
        {
            if (a[i] != b[i])
            {
                if (char.IsDigit(a[i]) && !char.IsDigit(b[i]))
                {
                    return -1;
                }
                else if (!char.IsDigit(a[i]) && char.IsDigit(b[i]))
                {
                    return 1;
                }
                else if (a[i] < b[i])
                {
                    return -1;
                }
                else
                {
                    return 1;
                }
            }
        }

        return a.Length.CompareTo(b.Length);
    }
}
```

