public class PermutationChecker
{
    public static bool IsPermutation(string str1, string str2)
    {
        if (str1.Length != str2.Length)
            return false;

        // Create dictionaries to count character occurrences
        Dictionary<char, int> dict1 = new Dictionary<char, int>();
        Dictionary<char, int> dict2 = new Dictionary<char, int>();

        // Count character occurrences in str1
        foreach (char c in str1)
        {
            if (c != ' ') // Ignore whitespace characters
            {
                if (dict1.ContainsKey(c))
                    dict1[c]++;
                else
                    dict1[c] = 1;
            }
        }

        // Count character occurrences in str2
        foreach (char c in str2)
        {
            if (c != ' ') // Ignore whitespace characters
            {
                if (dict2.ContainsKey(c))
                    dict2[c]++;
                else
                    dict2[c] = 1;
            }
        }

        // Compare character occurrences
        foreach (KeyValuePair<char, int> kvp in dict1)
        {
            if (!dict2.ContainsKey(kvp.Key) || dict2[kvp.Key] != kvp.Value)
                return false;
        }

        return true;
    }

