Here is an example implementation of an event listener class in PascalABC.NET that meets all the requirements:

```csharp
using System;
using System.Collections.Generic;

public class EventListener
{
    private Dictionary<string, Delegate> eventHandlers;
    private int numEventsFired;

    public EventListener()
    {
        eventHandlers = new Dictionary<string, Delegate>();
        numEventsFired = 0;
    }

    public void Subscribe(string eventName, Action<object[]> eventHandler)
    {
        if (!eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName] = null;
        }

        eventHandlers[eventName] = (Action<object[]>)eventHandlers[eventName] + eventHandler;
    }

    public void Unsubscribe(string eventName, Action<object[]> eventHandler)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName] = (Action<object[]>)eventHandlers[eventName] - eventHandler;

            if (eventHandlers[eventName] == null)
            {
                eventHandlers.Remove(eventName);
            }
        }
    }

    public void FireEvent(string eventName, params object[] parameters)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            Delegate eventHandler = eventHandlers[eventName];
            eventHandler?.DynamicInvoke(parameters);
            numEventsFired++;
        }
    }

    public bool IsSubscribed(string eventName)
    {
        return eventHandlers.ContainsKey(eventName);
    }

    public List<string> GetSubscribedEvents()
    {
        return new List<string>(eventHandlers.Keys);
    }

    public int GetNumSubscribedEvents()
    {
        return eventHandlers.Count;
    }

    public int GetNumEventsFired()
    {
        return numEventsFired;
    }
}
```

