```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        double value = 7.75;
        string stringValue = DoubleToString(value);
        Console.WriteLine(stringValue);
    }

    static string DoubleToString(double value)
    {
        bool isNegative = value < 0;
        if (isNegative)
        {
            value = -value;
        }

        long integerValue = (long)value;
        double decimalValue = value - integerValue;

        string integerPart = IntegerToString(integerValue);
        string decimalPart = DecimalToString(decimalValue);

        if (isNegative)
        {
            return "-" + integerPart + "." + decimalPart;
        }
        else
        {
            return integerPart + "." + decimalPart;
        }
    }

    static string IntegerToString(long value)
    {
        if (value == 0)
        {
            return "0";
        }

        string result = "";
        while (value > 0)
        {
            int digit = (int)(value % 10);
            result = (char)(digit + '0') + result;
            value /= 10;
        }

        return result;
    }

    static string DecimalToString(double value)
    {
        string result = "";
        const int precision = 15;

        for (int i = 0; i < precision; i++)
        {
            value *= 10;
            int digit = (int)value;
            result += (char)(digit + '0');
            value -= digit;
        }

        return result;
    }
}
```

