public static string InsertCharacter(string str, char character, int index)
{
    // Convert the string to a character array
    char[] charArray = str.ToCharArray();

    // Create space for the new character
    Array.Resize(ref charArray, charArray.Length + 1);

    // Shift all characters from the given index to the right
    for (int i = charArray.Length - 1; i > index; i--)
    {
        charArray[i] = charArray[i - 1];
    }

    // Insert the new character at the given index
    charArray[index] = character;

