```csharp
using System;

class NumberToWordsConverter
{
    private static string[] ones = { "", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
                                    "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen" };

    private static string[] tens = { "", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety" };

    private static string[] thousands = { "", "Thousand", "Million", "Billion", "Trillion" };

    private static string ConvertNumberToWords(long number)
    {
        if (number == 0)
        {
            return "Zero";
        }

        string words = "";
        int index = 0;

        while (number > 0)
        {
            if (number % 1000 != 0)
            {
                words = ConvertHundredsToWords((int)(number % 1000)) + thousands[index] + " " + words;
            }

            number /= 1000;
            index++;
        }

        return words.Trim();
    }

    private static string ConvertHundredsToWords(int number)
    {
        string words = "";

        if (number % 100 < 20)
        {
            words = ones[number % 100];
            number /= 100;
        }
        else
        {
            words = ones[number % 10];
            number /= 10;

            words = tens[number % 10] + " " + words;
            number /= 10;
        }

        if (number != 0)
        {
            return ones[number] + " Hundred " + words;
        }

        return words;
    }

    static void Main()
    {
        Console.Write("Enter a number: ");
        long number = long.Parse(Console.ReadLine());

        string words = ConvertNumberToWords(number);

        Console.WriteLine("Number in words: " + words);
    }
}
```

This code defines a `NumberToWordsConverter` class that contains two helper methods: `ConvertNumberToWords` and `ConvertHundredsToWords`. The `ConvertNumberToWords` method converts a given number to words by dividing it into groups of three digits (thousands) and then converting each group to words. The `ConvertHundredsToWords` method converts a three-digit number to words by handling the cases for numbers less than 20 and numbers greater than or equal to 20 separately.

In the `Main` method, the user is prompted to enter a number, and then the `ConvertNumberToWords` method is called to convert the number to words. The result is then displayed on the console.

