class Program
{
    static void Main(string[] args)
    {
        int limit = 100;
        List<int> fibonacciPrimes = GenerateFibonacciPrimes(limit);
        foreach (int number in fibonacciPrimes)
        {
            Console.WriteLine(number);
        }
    }

    static List<int> GenerateFibonacciPrimes(int limit)
    {
        List<int> fibonacciPrimes = new List<int>();
        int a = 0;
        int b = 1;
        int c = 0;

        while (c <= limit)
        {
            if (IsPrime(c))
            {
                fibonacciPrimes.Add(c);
            }
            c = a + b;
            a = b;
            b = c;
        }

        return fibonacciPrimes;
    }

    static bool IsPrime(int number)
    {
        if (number <= 1)
        {
            return false;
        }

        for (int i = 2; i * i <= number; i++)
        {
            if (number % i == 0)
            {
                return false;
            }
        }

        return true;
    }
}
```

