public bool AreAllCharactersUnique(string input)
{
    if (input.Length > 128) // Assuming ASCII character set
    {
        return false;
    }

    bool[] charSet = new bool[128];

    for (int i = 0; i < input.Length; i++)
    {
        int val = input[i];

        if (charSet[val])
        {
            return false;
        }

        charSet[val] = true;
    }

    return true;
}
