public int StringToInteger(string s)
{
    // Remove leading and trailing white spaces
    s = s.Trim();

    // Check if the string is empty
    if (string.IsNullOrEmpty(s))
    {
        return 0;
    }

    // Check if the string starts with a valid sign (+ or -)
    bool isNegative = false;
    if (s[0] == '-')
    {
        isNegative = true;
        s = s.Substring(1);
    }
    else if (s[0] == '+')
    {
        s = s.Substring(1);
    }

    int result = 0;
    int maxLength = isNegative ? 11 : 10; // Maximum length considering the sign

    // Iterate through each character of the string
    foreach (char c in s)
    {
        // Check if the character is a digit
        if (char.IsDigit(c))
        {
            // Multiply the result by 10 and add the digit value
            result = result * 10 + (c - '0');

            // Check if the result exceeds the maximum length
            if (result.ToString().Length > maxLength)
            {
                break;
            }
        }
        else
        {
            // Return 0 if the string contains any non-digit characters
            return 0;
        }
    }

    // Apply the sign if necessary
    if (isNegative)
    {
        result = -result;
    }

    // Check if the result exceeds the range of a 32-bit signed integer
    if (result < int.MinValue)
    {
        return int.MinValue;
    }
    else if (result > int.MaxValue)
    {
        return int.MaxValue;
    }

    return result;
}
```

