    public (int, int) SearchValue(int[,] arr, int target)
    {
        int numRows = arr.GetLength(0);
        int numCols = arr.GetLength(1);
        int low = 0;
        int high = numRows * numCols - 1;

        while (low <= high)
        {
            int mid = (low + high) / 2;
            int row = mid / numCols;
            int col = mid % numCols;

            int value = arr[row, col];

            if (value == target)
            {
                return (row, col);
            }
            else if (value < target)
            {
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }

        return (-1, -1);
    }

    public int SearchRow(int[,] arr, int target)
    {
        int numRows = arr.GetLength(0);
        int numCols = arr.GetLength(1);

        for (int row = 0; row < numRows; row++)
        {
            int low = 0;
            int high = numCols - 1;

            while (low <= high)
            {
                int mid = (low + high) / 2;
                int value = arr[row, mid];

                if (value == target)
                {
                    return row;
                }
                else if (value < target)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
        }

        return -1;
    }

    public int SearchColumn(int[,] arr, int target)
    {
        int numRows = arr.GetLength(0);
        int numCols = arr.GetLength(1);

        for (int col = 0; col < numCols; col++)
        {
            int low = 0;
            int high = numRows - 1;

            while (low <= high)
            {
                int mid = (low + high) / 2;
                int value = arr[mid, col];

                if (value == target)
                {
                    return col;
                }
                else if (value < target)
                {
                    low = mid + 1;
                }
                else
                {
                    high = mid - 1;
                }
            }
        }

        return -1;
    }

    public (int, int) SearchSubmatrix(int[,] arr, int[,] submatrix)
    {
        int numRows = arr.GetLength(0);
        int numCols = arr.GetLength(1);
        int subNumRows = submatrix.GetLength(0);
        int subNumCols = submatrix.GetLength(1);

        for (int row = 0; row <= numRows - subNumRows; row++)
        {
            for (int col = 0; col <= numCols - subNumCols; col++)
            {
                bool found = true;

                for (int subRow = 0; subRow < subNumRows; subRow++)
                {
                    for (int subCol = 0; subCol < subNumCols; subCol++)
                    {
                        if (arr[row + subRow, col + subCol] != submatrix[subRow, subCol])
                        {
                            found = false;
                            break;
                        }
                    }

                    if (!found)
                    {
                        break;
                    }
                }

                if (found)
                {
                    return (row, col);
                }
            }
        }

        return (-1, -1);
    }
}
```

