using System;
using System.Numerics;

public class Program
{
    public static Complex[] FindRoots(double a, double b, double c, double d)
    {
        Complex[] roots = new Complex[3];

        Complex discriminant = Complex.Pow(b, 2) - (3 * a * c);
        Complex sqrtDiscriminant = Complex.Sqrt(discriminant);

        Complex alpha = (2 * b * b * b - 9 * a * b * c + 27 * a * a * d + Complex.Pow((sqrtDiscriminant + b * b - 3 * a * c) / (2 * sqrtDiscriminant), 3)) / (2 * Complex.Pow(sqrtDiscriminant, 3));
        Complex omega = new Complex(-0.5, Math.Sqrt(3) / 2);

        for (int k = 0; k < 3; k++)
        {
            Complex root = Complex.Pow(alpha + omega * Complex.Pow(sqrtDiscriminant, k), 1.0 / 3.0);
            roots[k] = root - (b / (3 * a));
        }

        return roots;
    }

    public static void Main(string[] args)
    {
