        double b = 0;
        double c = -3;
        double d = -2;

        Complex[] roots = FindRoots(a, b, c, d);

        Console.WriteLine("Roots:");
        foreach (Complex root in roots)
        {
            Console.WriteLine(root);
        }
    }
}
