{
    public static void Main(string[] args)
    {
        MyCustomList myList = new MyCustomList();
        myList.Add("Hello");
        myList.Add("World");
        myList.Add("Custom");
        myList.Add("List");

        for (int i = 0; i < myList.Size; i++)
        {
            Console.WriteLine(myList.Get(i));
        }
    }
}
