```csharp
using System;
using System.Collections.Generic;

public class Program
{
    public static void Main(string[] args)
    {
        int[] arr1 = { 8, 15, 20, 7, 2 };
        int[] arr2 = { 5, 6, 7, 9, 8 };

        int thirdCommonElement = FindThirdCommonElement(arr1, arr2);
        Console.WriteLine("The third common element is: " + thirdCommonElement);
    }

    public static int FindThirdCommonElement(int[] arr1, int[] arr2)
    {
        // Create a dictionary to store the frequency of elements in arr1
        Dictionary<int, int> frequencyMap = new Dictionary<int, int>();

        // Iterate through arr1 and update the frequency map
        foreach (int num in arr1)
        {
            if (frequencyMap.ContainsKey(num))
            {
                frequencyMap[num]++;
            }
            else
            {
                frequencyMap.Add(num, 1);
            }
        }

        // Iterate through arr2 and check if each element exists in the frequency map
        // Also keep track of the count of common elements
        int commonCount = 0;
        foreach (int num in arr2)
        {
            if (frequencyMap.ContainsKey(num))
            {
                commonCount++;
                if (commonCount == 3)
                {
                    return num; // Return the third common element
                }
            }
        }

        // If there is no third common element, return -1
        return -1;
    }
}
