    {
        // Regex pattern to match the page title
        string pattern = @"<title>(.*?)</title>";

        // Match the pattern in the HTML
        Match match = Regex.Match(html, pattern);

        // Extract the page title
        if (match.Success)
        {
            return match.Groups[1].Value;
        }
        else
