```csharp
using System;

public class PalindromeChecker
{
    public static bool IsPalindrome(string input)
    {
        // Convert the input string to lowercase and remove non-alphanumeric characters
        string cleanedInput = RemoveNonAlphanumeric(input.ToLower());

        // Compare the cleaned input string with its reversed version
        return cleanedInput == ReverseString(cleanedInput);
    }

    private static string RemoveNonAlphanumeric(string input)
    {
        // Create a new char array to store the alphanumeric characters
        char[] cleanedArray = new char[input.Length];
        int currentIndex = 0;

        // Iterate through each character in the input string
        foreach (char c in input)
        {
            // Check if the character is alphanumeric
            if (Char.IsLetterOrDigit(c))
            {
                // If it is, add it to the cleaned array
                cleanedArray[currentIndex] = c;
                currentIndex++;
            }
        }

        // Create a new string from the cleaned array
        return new string(cleanedArray, 0, currentIndex);
    }

    private static string ReverseString(string input)
    {
        char[] charArray = input.ToCharArray();
        Array.Reverse(charArray);
        return new string(charArray);
    }

    public static void Main(string[] args)
    {
        string input = "A man, a plan, a canal, Panama!";
        Console.WriteLine(IsPalindrome(input)); // Output: True

        input = "Hello world";
        Console.WriteLine(IsPalindrome(input)); // Output: False
    }
}
```

In this example, the `IsPalindrome` function first converts the input string to lowercase and removes all non-alphanumeric characters using the `RemoveNonAlphanumeric` function. It then checks if the cleaned input string is equal to its reversed version, using the `ReverseString` function.

