Here's an example of a PascalABC.NET program that reads an array of strings and sorts them in alphabetical order using the bubble sort algorithm:

```csharp
using System;

class Program
{
    static void Main(string[] args)
    {
        // Read the array of strings from the user
        Console.WriteLine("Enter the number of strings:");
        int n = int.Parse(Console.ReadLine());

        string[] arr = new string[n];
        Console.WriteLine("Enter the strings:");

        for (int i = 0; i < n; i++)
        {
            arr[i] = Console.ReadLine();
        }

        // Sort the array using bubble sort
        BubbleSort(arr);

        // Display the sorted array
        Console.WriteLine("Sorted array:");
        foreach (string str in arr)
        {
            Console.WriteLine(str);
        }
    }

    static void BubbleSort(string[] arr)
    {
        int n = arr.Length;
        bool swapped;

        for (int i = 0; i < n - 1; i++)
        {
            swapped = false;
            for (int j = 0; j < n - i - 1; j++)
            {
                if (string.Compare(arr[j], arr[j + 1]) > 0)
                {
                    // Swap arr[j] and arr[j+1]
                    string temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                    swapped = true;
                }
            }

            // If no two elements were swapped in the inner loop, then the array is already sorted
            if (!swapped)
            {
                break;
            }
        }
    }
}
```

In this program, we first read the number of strings and then read the strings themselves from the user. Then, we use the bubble sort algorithm to sort the array in alphabetical order. Finally, we display the sorted array to the user. The bubble sort algorithm works by repeatedly swapping adjacent elements if they are in the wrong order until the array is sorted.

