```csharp
public static void ShuffleArray(int[] array)
{
    Random random = new Random();
    int length = array.Length;

    // Shuffle the array
    for (int i = 0; i < length; i++)
    {
        // Generate a random index
        int randomIndex = random.Next(i, length);

        // Swap the current element with the element at the random index
        int temp = array[randomIndex];
        array[randomIndex] = array[i];
        array[i] = temp;
    }

    // Rearrange the array so that odd numbers come before even numbers
    int left = 0;
    int right = length - 1;

    while (left < right)
    {
        // Find the next odd number from the left side
        while (left < right && array[left] % 2 == 1)
        {
            left++;
        }

        // Find the next even number from the right side
        while (left < right && array[right] % 2 == 0)
        {
            right--;
        }

        // Swap the odd number with the even number
        int temp = array[left];
        array[left] = array[right];
        array[right] = temp;
    }
}
```

