public class Program
{
    public static bool IsPermutation(string str1, string str2)
    {
        // Step 1: Remove whitespace characters and punctuation marks
        string cleanedStr1 = RemoveNonAlphanumeric(str1);
        string cleanedStr2 = RemoveNonAlphanumeric(str2);

        // Step 2: Check if the cleaned strings have the same length
        if (cleanedStr1.Length != cleanedStr2.Length)
        {
            return false;
        }

        // Step 3: Convert the strings to lowercase for case insensitivity
        cleanedStr1 = cleanedStr1.ToLower();
        cleanedStr2 = cleanedStr2.ToLower();

        // Step 4: Create character frequency dictionaries for both strings
        Dictionary<char, int> freqDict1 = GetCharacterFrequencies(cleanedStr1);
        Dictionary<char, int> freqDict2 = GetCharacterFrequencies(cleanedStr2);

        // Step 5: Check if the character frequency dictionaries are equal
        return AreDictionariesEqual(freqDict1, freqDict2);
    }

    private static string RemoveNonAlphanumeric(string str)
    {
        // Remove whitespace characters and punctuation marks using regular expression
        return System.Text.RegularExpressions.Regex.Replace(str, @"[^a-zA-Z0-9]", "");
    }

    private static Dictionary<char, int> GetCharacterFrequencies(string str)
    {
        Dictionary<char, int> freqDict = new Dictionary<char, int>();

        foreach (char c in str)
        {
            if (freqDict.ContainsKey(c))
            {
                freqDict[c]++;
            }
            else
            {
                freqDict[c] = 1;
            }
        }

        return freqDict;
    }

    private static bool AreDictionariesEqual(Dictionary<char, int> dict1, Dictionary<char, int> dict2)
    {
        if (dict1.Count != dict2.Count)
        {
            return false;
        }

        foreach (var kvp in dict1)
        {
            char key = kvp.Key;
            int value1 = kvp.Value;

            if (!dict2.ContainsKey(key) || dict2[key] != value1)
            {
                return false;
            }
        }

        return true;
    }

    public static void Main(string[] args)
    {
        string str1 = "abc";
        string str2 = "a bc";

        bool isPermutation = IsPermutation(str1, str2);
        Console.WriteLine(isPermutation);  // Output: True
    }
}
