```csharp
using System;

class Triangle
{
    static void Main()
    {
        Console.WriteLine("Enter the lengths of the triangle sides:");
        double side1 = double.Parse(Console.ReadLine());
        double side2 = double.Parse(Console.ReadLine());
        double side3 = double.Parse(Console.ReadLine());

        if (IsValidTriangle(side1, side2, side3))
        {
            Console.WriteLine("Area of the triangle: " + CalculateArea(side1, side2, side3));

            Console.WriteLine("Is equilateral: " + IsEquilateral(side1, side2, side3));
            Console.WriteLine("Is isosceles: " + IsIsosceles(side1, side2, side3));
            Console.WriteLine("Is scalene: " + IsScalene(side1, side2, side3));
            Console.WriteLine("Is right-angled: " + IsRightAngled(side1, side2, side3));
            Console.WriteLine("Is obtuse-angled: " + IsObtuseAngled(side1, side2, side3));
            Console.WriteLine("Is acute-angled: " + IsAcuteAngled(side1, side2, side3));
        }
        else
        {
            Console.WriteLine("Invalid triangle.");
        }
    }

    static bool IsValidTriangle(double side1, double side2, double side3)
    {
        return side1 + side2 > side3 && side1 + side3 > side2 && side2 + side3 > side1;
    }

    static double CalculateArea(double side1, double side2, double side3)
    {
        double s = (side1 + side2 + side3) / 2;
        return Math.Sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }

    static bool IsEquilateral(double side1, double side2, double side3)
    {
        return side1 == side2 && side2 == side3;
    }

    static bool IsIsosceles(double side1, double side2, double side3)
    {
        return side1 == side2 || side1 == side3 || side2 == side3;
    }

    static bool IsScalene(double side1, double side2, double side3)
    {
        return side1 != side2 && side1 != side3 && side2 != side3;
    }

    static bool IsRightAngled(double side1, double side2, double side3)
    {
        double a = side1 * side1;
        double b = side2 * side2;
        double c = side3 * side3;

        return a == b + c || b == a + c || c == a + b;
    }

    static bool IsObtuseAngled(double side1, double side2, double side3)
    {
        double a = side1 * side1;
        double b = side2 * side2;
        double c = side3 * side3;

        return a > b + c || b > a + c || c > a + b;
    }

    static bool IsAcuteAngled(double side1, double side2, double side3)
    {
        return !IsRightAngled(side1, side2, side3) && !IsObtuseAngled(side1, side2, side3);
    }
