using CsvHelper;

namespace EmployeeDataTransformation
{
    public class Employee
    {
        public int EmployeeID { get; set; }
        public string FirstName { get; set; }
        public string LastName { get; set; }
        public int Age { get; set; }
        public string Department { get; set; }
        public decimal Salary { get; set; }
    }

    public class TransformedData
    {
        public string Department { get; set; }
        public decimal AverageSalary { get; set; }
        public Employee OldestEmployee { get; set; }
        public decimal TotalSalaryExpenditure { get; set; }
        public decimal StandardDeviation { get; set; }
        public Employee HighestSalaryEmployee { get; set; }
    }

    public class EmployeeDataProcessor
    {
        private string connectionString;

        public EmployeeDataProcessor(string connectionString)
        {
            this.connectionString = connectionString;
        }

        public List<Employee> ReadEmployees()
        {
            List<Employee> employees = new List<Employee>();

            using (SqlConnection connection = new SqlConnection(connectionString))
            {
                string query = "SELECT * FROM Employees";
                SqlCommand command = new SqlCommand(query, connection);
                connection.Open();

                SqlDataReader reader = command.ExecuteReader();

                while (reader.Read())
                {
                    Employee employee = new Employee()
                    {
                        EmployeeID = (int)reader["EmployeeID"],
                        FirstName = (string)reader["FirstName"],
                        LastName = (string)reader["LastName"],
                        Age = (int)reader["Age"],
                        Department = (string)reader["Department"],
                        Salary = (decimal)reader["Salary"]
                    };

                    employees.Add(employee);
                }

                reader.Close();
            }

            return employees;
        }

        public List<TransformedData> ApplyTransformations(List<Employee> employees)
        {
            var transformedData = employees.GroupBy(e => e.Department)
                                           .Select(g => new TransformedData()
                                           {
                                               Department = g.Key,
                                               AverageSalary = g.Average(e => e.Salary),
                                               OldestEmployee = g.OrderByDescending(e => e.Age).First(),
                                               TotalSalaryExpenditure = g.Sum(e => e.Salary),
                                               StandardDeviation = CalculateStandardDeviation(g.Select(e => e.Salary)),
                                               HighestSalaryEmployee = g.OrderByDescending(e => e.Salary).First()
                                           })
                                           .OrderBy(td => td.Department)
                                           .ToList();

            return transformedData;
        }

        private decimal CalculateStandardDeviation(IEnumerable<decimal> values)
        {
            decimal average = values.Average();
            decimal sumOfSquares = values.Sum(v => (v - average) * (v - average));
            decimal variance = sumOfSquares / values.Count();
            decimal standardDeviation = (decimal)Math.Sqrt((double)variance);
            return standardDeviation;
        }

        public List<TransformedData> PaginateData(List<TransformedData> transformedData, int page)
        {
            int pageSize = 10;
            int startIndex = (page - 1) * pageSize;
            int endIndex = Math.Min(startIndex + pageSize, transformedData.Count);

            return transformedData.GetRange(startIndex, endIndex - startIndex);
        }

        public List<TransformedData> SearchData(List<TransformedData> transformedData, string searchQuery)
        {
            return transformedData.Where(td => td.Department.ToLower().Contains(searchQuery.ToLower()) ||
                                               td.HighestSalaryEmployee.FirstName.ToLower().Contains(searchQuery.ToLower()) ||
                                               td.HighestSalaryEmployee.LastName.ToLower().Contains(searchQuery.ToLower()))
                                  .ToList();
        }

