```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;

public class EventListener
{
    private readonly ConcurrentDictionary<string, EventHandler> eventHandlers;
    private readonly ConcurrentDictionary<string, int> eventCounters;

    public EventListener()
    {
        eventHandlers = new ConcurrentDictionary<string, EventHandler>();
        eventCounters = new ConcurrentDictionary<string, int>();
    }

    public void Subscribe(string eventName, EventHandler handler)
    {
        eventHandlers[eventName] = handler;
        eventCounters[eventName] = 0;
    }

    public void Unsubscribe(string eventName)
    {
        eventHandlers.TryRemove(eventName, out _);
        eventCounters.TryRemove(eventName, out _);
    }

    public void FireEvent(string eventName, params object[] args)
    {
        if (eventHandlers.TryGetValue(eventName, out EventHandler handler))
        {
            Interlocked.Increment(ref eventCounters[eventName]);
            ThreadPool.QueueUserWorkItem(_ => handler.Invoke(args));
        }
    }

    public bool IsSubscribed(string eventName)
    {
        return eventHandlers.ContainsKey(eventName);
    }

    public IList<string> GetSubscribedEvents()
    {
        return new List<string>(eventHandlers.Keys);
    }

    public int GetNumSubscribedEvents()
    {
        return eventHandlers.Count;
    }

    public int GetNumEventsFired()
    {
        int totalFired = 0;
        foreach (int count in eventCounters.Values)
        {
            totalFired += count;
        }
        return totalFired;
    }
}

public delegate void EventHandler(params object[] args);
```

The implementation uses the `ConcurrentDictionary` class from the `System.Collections.Concurrent` namespace to store the event handlers and event counters. This ensures thread-safe access to these collections.

To handle multiple events, the event handlers are stored in a dictionary, with the event name as the key and the event handler as the value.

To handle multiple threads subscribing, unsubscribing, and firing events simultaneously, the `ConcurrentDictionary` is used to ensure thread-safe access to the event handlers and event counters. The `Interlocked.Increment` method is used to increment the event counter in a thread-safe manner.

The `FireEvent` method checks if the event handler for the given event name exists, and if so, it increments the event counter and queues the invocation of the event handler on a thread pool thread. The event handler is invoked with the provided arguments.

The `IsSubscribed` method checks if the event handler for the given event name exists in the event handlers dictionary.

The `GetSubscribedEvents` method returns a list of all event names in the event handlers dictionary.

The `GetNumSubscribedEvents` method returns the count of event handlers in the event handlers dictionary.

The `GetNumEventsFired` method calculates the total number of events fired by summing up the event counters.

Note that this implementation assumes that the event handlers are responsible for handling any exceptions that may occur during event invocation.

