using System;

class Program
{
    static void Main()
    {
        // Example usage
        var array = new object[] { 1, "2", 3, "2", 4, "5", 6 };
        var itemToRemove = "2";

        RemoveOccurrences(array, itemToRemove);

        foreach (var item in array)
        {
            Console.WriteLine(item);
        }
