    static void RemoveOccurrences<T>(T[] array, T itemToRemove)
    {
        int writeIndex = 0;

        for (int i = 0; i < array.Length; i++)
        {
            if (!Equals(array[i], itemToRemove))
            {
                array[writeIndex] = array[i];
                writeIndex++;
            }
        }

